// Stateless Responses API function-calling loop. Tool outputs and screenshots remain in memory.
internal sealed class ChatGptAgentRunner {
 static readonly JsonElement[] Tools=JsonSerializer.Deserialize<JsonElement[]>("""
 [{"type":"function","name":"read_file","description":"Read a UTF-8 text file in the workspace.","parameters":{"type":"object","properties":{"path":{"type":"string"}},"required":["path"],"additionalProperties":false}},
 {"type":"function","name":"list_files","description":"List files in the workspace, optionally matching a search pattern.","parameters":{"type":"object","properties":{"path":{"type":"string"},"pattern":{"type":"string"}},"additionalProperties":false}},
 {"type":"function","name":"search_files","description":"Search text files in the workspace with a regular expression.","parameters":{"type":"object","properties":{"path":{"type":"string"},"pattern":{"type":"string"}},"required":["pattern"],"additionalProperties":false}},
 {"type":"function","name":"write_file","description":"Create or replace a UTF-8 text file.","parameters":{"type":"object","properties":{"path":{"type":"string"},"content":{"type":"string"}},"required":["path","content"],"additionalProperties":false}},
 {"type":"function","name":"edit_file","description":"Replace exactly one matching text segment in a file.","parameters":{"type":"object","properties":{"path":{"type":"string"},"old_text":{"type":"string"},"new_text":{"type":"string"}},"required":["path","old_text","new_text"],"additionalProperties":false}},
 {"type":"function","name":"run_command","description":"Run a PowerShell command in the workspace.","parameters":{"type":"object","properties":{"command":{"type":"string"}},"required":["command"],"additionalProperties":false}},
 {"type":"function","name":"fetch_url","description":"Fetch a public HTTPS page and return its text.","parameters":{"type":"object","properties":{"url":{"type":"string"}},"required":["url"],"additionalProperties":false}}]
 """)!;
 readonly Func<AgentApproval,CancellationToken,Task<bool>> ask;readonly Action<string,JsonElement>? preview;readonly HttpClient http;readonly Func<Task<string>> tokenSource;
 public ChatGptAgentRunner(Func<AgentApproval,CancellationToken,Task<bool>> ask,Action<string,JsonElement>? preview=null,HttpClient? http=null,Func<Task<string>>? tokenSource=null){this.ask=ask;this.preview=preview;this.http=http??new HttpClient{Timeout=Timeout.InfiniteTimeSpan};this.tokenSource=tokenSource??throw new ArgumentNullException(nameof(tokenSource));}
 public async Task<string> RunAsync(string text,byte[]? image,string model,IReadOnlyList<(string Role,string Text)> history,AgentSettings settings,Action<string> update,CancellationToken token){
  if(string.IsNullOrWhiteSpace(settings.Workspace)){Directory.CreateDirectory(ClaudeAgentRunner.DefaultWorkspace);settings=settings with{Workspace=ClaudeAgentRunner.DefaultWorkspace};}
  using var mcp=settings.Tools.Contains("desktop")?new McpClient():null;using var killMcp=token.Register(()=>mcp?.Kill());var tools=Tools.ToList();if(mcp is not null)tools.AddRange(mcp.ListTools());
  var input=new List<object>();foreach(var h in history.TakeLast(12))input.Add(new{role=h.Role,content=h.Text});
  var content=new List<object>{new{type="input_text",text}};if(image is not null)content.Add(new{type="input_image",image_url="data:image/jpeg;base64,"+Convert.ToBase64String(image)});input.Add(new{role="user",content});
  var steps=new List<string>();var answer="";
  for(int round=0;round<30;round++){
   token.ThrowIfCancellationRequested();var instructions=ClaudeAgentRunner.SystemPrompt(settings.Workspace).Replace("mcp__desktop__","desktop_",StringComparison.Ordinal)+" Use the available functions when the user asks you to perform a task. Never retry a denied action. Report what changed, and do not claim an action succeeded unless a tool confirms it.";var body=JsonSerializer.Serialize(new{model,input,tools,store=false,stream=true,instructions});
   using var req=new HttpRequestMessage(HttpMethod.Post,"https://api.openai.com/v1/responses");req.Headers.Authorization=new AuthenticationHeaderValue("Bearer",await tokenSource());req.Content=new StringContent(body,Encoding.UTF8,"application/json");
   using var res=await http.SendAsync(req,HttpCompletionOption.ResponseHeadersRead,token);if(!res.IsSuccessStatusCode)throw new InvalidOperationException($"ChatGPT agent request failed (HTTP {(int)res.StatusCode}).");
   var items=new List<JsonElement>();var calls=new List<JsonElement>();var completed=false;answer="";
   using var reader=new StreamReader(await res.Content.ReadAsStreamAsync(token));string? line;
   while((line=await reader.ReadLineAsync(token)) is not null){if(!line.StartsWith("data: ",StringComparison.Ordinal))continue;var data=line[6..];if(data=="[DONE]")break;using var ev=JsonDocument.Parse(data);var root=ev.RootElement;var type=root.TryGetProperty("type",out var t)?t.GetString():null;
    if(type=="response.output_text.delta"){answer+=root.GetProperty("delta").GetString();update(Compose());}
    else if(type=="response.output_item.done"&&root.TryGetProperty("item",out var item)){var clone=item.Clone();items.Add(clone);if(item.TryGetProperty("type",out var it)&&it.GetString()=="function_call")calls.Add(clone);}
    else if(type=="response.completed")completed=true;
    else if(type=="response.failed")throw new InvalidOperationException("ChatGPT could not complete the agent request.");
   }
   if(!completed)throw new InvalidOperationException("The connection ended before ChatGPT completed the agent response.");
   foreach(var item in items)input.Add(item);
   if(calls.Count==0)return Compose();
   foreach(var call in calls){token.ThrowIfCancellationRequested();var name=call.GetProperty("name").GetString()??"";var args=JsonDocument.Parse(call.GetProperty("arguments").GetString()??"{}").RootElement.Clone();var desktop=name.StartsWith("desktop_",StringComparison.Ordinal);var mapped=desktop?AgentPolicy.DesktopPrefix+name[8..]:Map(name);using var policyDoc=JsonDocument.Parse(PolicyInput(name,args));var policyArgs=policyDoc.RootElement;var (decision,reason)=AgentPolicy.Decide(mapped,policyArgs,settings);var allowed=decision==AgentDecision.Allow;
    var title=ClaudeAgentRunner.Describe(mapped,policyArgs,settings.Workspace);
    preview?.Invoke(mapped,args);
    if(decision==AgentDecision.Ask){using var timeout=CancellationTokenSource.CreateLinkedTokenSource(token);timeout.CancelAfter(TimeSpan.FromMinutes(5));try{allowed=await ask(new AgentApproval(Guid.NewGuid().ToString("N"),mapped,title,ClaudeAgentRunner.Detail(mapped,policyArgs)),timeout.Token);reason=allowed?null:"The user denied this action.";}catch(OperationCanceledException){allowed=false;reason=token.IsCancellationRequested?"The user stopped the agent.":"Approval timed out; action denied.";}}
    string output;if(!allowed){output="DENIED: "+(reason??"Not allowed.")+" Do not retry this action.";steps.Add(title+" · denied");}else{try{output=desktop?mcp!.Call(name[8..],args,token):await Execute(name,args,settings,token,settings.Approval=="auto"||decision==AgentDecision.Ask&&allowed);steps.Add(title);}catch(Exception e){output="ERROR: "+e.Message;steps.Add(title+" · failed");}}
    input.Add(new{type="function_call_output",call_id=call.GetProperty("call_id").GetString(),output});if(desktop&&name=="desktop_screenshot")foreach(var imageData in mcp!.LastImages)input.Add(new{role="user",content=new object[]{new{type="input_image",image_url="data:image/jpeg;base64,"+imageData}}});update(Compose());
   }
  }
  throw new InvalidOperationException("ChatGPT reached the 30-round agent limit.");
  string Compose()=>steps.Count==0?answer:"**Steps**\n"+string.Join("\n",steps.Select(s=>"- "+s))+"\n\n"+answer;
 }
 static string Map(string n)=>n switch{"read_file" or "list_files"=>"Read","search_files"=>"Grep","write_file"=>"Write","edit_file"=>"Edit","run_command"=>"PowerShell","fetch_url"=>"WebFetch",_=>n};
 static string PolicyInput(string name,JsonElement args){if(name.StartsWith("desktop_",StringComparison.Ordinal))return args.GetRawText();var input=System.Text.Json.Nodes.JsonNode.Parse(args.GetRawText())?.AsObject()??new();if(input["path"] is {} path)input["file_path"]=path.DeepClone();if(input["old_text"] is {} old)input["old_string"]=old.DeepClone();if(input["new_text"] is {} replacement)input["new_string"]=replacement.DeepClone();return input.ToJsonString();}
 static async Task<string> Execute(string name,JsonElement a,AgentSettings s,CancellationToken token,bool allowOutside){
  string Arg(string n)=>a.TryGetProperty(n,out var v)?v.GetString()??"":"";
  var path=Arg("path");string Full()=>!AgentPolicy.Inside(path,s.Workspace)&&allowOutside?Path.GetFullPath(path,s.Workspace):SafeWorkspacePath(path,s.Workspace);
  switch(name){
   case "read_file":return (await File.ReadAllTextAsync(Full(),token)) is var r&&r.Length>100000?r[..100000]+"\n[truncated]":r;
   case "list_files":{var root=string.IsNullOrEmpty(path)?s.Workspace:Full();var pattern=string.IsNullOrEmpty(Arg("pattern"))?"*":Arg("pattern");var files=new List<string>();foreach(var file in Directory.EnumerateFiles(root,pattern,SearchOption.AllDirectories).Take(500)){try{SafeWorkspacePath(Path.GetRelativePath(s.Workspace,file),s.Workspace);files.Add(Path.GetRelativePath(s.Workspace,file));if(files.Count==300)break;}catch(InvalidOperationException){}}return string.Join("\n",files);}
   case "search_files":{var root=string.IsNullOrEmpty(path)?s.Workspace:Full();var regex=new System.Text.RegularExpressions.Regex(Arg("pattern"),System.Text.RegularExpressions.RegexOptions.IgnoreCase,TimeSpan.FromSeconds(2));var matches=new List<string>();foreach(var file in Directory.EnumerateFiles(root,"*",SearchOption.AllDirectories).Take(500)){token.ThrowIfCancellationRequested();try{SafeWorkspacePath(Path.GetRelativePath(s.Workspace,file),s.Workspace);var lines=await File.ReadAllLinesAsync(file,token);for(int i=0;i<lines.Length&&matches.Count<200;i++)if(regex.IsMatch(lines[i]))matches.Add($"{Path.GetRelativePath(s.Workspace,file)}:{i+1}: {lines[i]}");}catch(IOException){}catch(InvalidOperationException){}}return string.Join("\n",matches);}
   case "write_file":{var f=Full();Directory.CreateDirectory(Path.GetDirectoryName(f)!);await File.WriteAllTextAsync(f,Arg("content"),token);return "File written.";}
   case "edit_file":{var f=Full();var original=await File.ReadAllTextAsync(f,token);var old=Arg("old_text");var index=original.IndexOf(old,StringComparison.Ordinal);if(old.Length==0||index<0||original.IndexOf(old,index+old.Length,StringComparison.Ordinal)>=0)throw new InvalidOperationException("The old text must appear exactly once in the file.");await File.WriteAllTextAsync(f,original[..index]+Arg("new_text")+original[(index+old.Length)..],token);return "File edited.";}
   case "run_command":{var cmd=Arg("command");if(cmd.Length>8000)throw new InvalidOperationException("Command is too long.");using var p=new Process{StartInfo=new ProcessStartInfo("powershell.exe","-NoProfile -NonInteractive -Command "+Quote(cmd)){WorkingDirectory=s.Workspace,UseShellExecute=false,RedirectStandardOutput=true,RedirectStandardError=true,CreateNoWindow=true}};foreach(var secret in new[]{"ANTHROPIC_API_KEY","ANTHROPIC_AUTH_TOKEN","OPENAI_API_KEY"})p.StartInfo.Environment.Remove(secret);p.Start();using var timeout=CancellationTokenSource.CreateLinkedTokenSource(token);timeout.CancelAfter(TimeSpan.FromMinutes(2));using var reg=timeout.Token.Register(()=>{try{p.Kill(true);}catch{}});var stdout=ReadCappedAsync(p.StandardOutput,30000,timeout.Token);var stderr=ReadCappedAsync(p.StandardError,30000,timeout.Token);await p.WaitForExitAsync(timeout.Token);return await stdout+"\n"+await stderr;}
   case "fetch_url":{var uri=new Uri(Arg("url"));if(uri.Scheme!="https")throw new InvalidOperationException("Only HTTPS URLs are allowed.");foreach(var ip in await System.Net.Dns.GetHostAddressesAsync(uri.Host,token)){var bytes=ip.GetAddressBytes();var privateIp=System.Net.IPAddress.IsLoopback(ip)||ip.IsIPv6LinkLocal||ip.IsIPv6SiteLocal||ip.IsIPv6UniqueLocal||ip.IsIPv4MappedToIPv6&&System.Net.IPAddress.IsLoopback(ip.MapToIPv4())||(ip.AddressFamily==System.Net.Sockets.AddressFamily.InterNetwork&&(bytes[0]==10||bytes[0]==127||bytes[0]==169&&bytes[1]==254||bytes[0]==172&&bytes[1]>=16&&bytes[1]<=31||bytes[0]==192&&bytes[1]==168));if(privateIp)throw new InvalidOperationException("Private network addresses are not allowed.");}using var c=CancellationTokenSource.CreateLinkedTokenSource(token);c.CancelAfter(TimeSpan.FromSeconds(15));using var client=new HttpClient(new HttpClientHandler{AllowAutoRedirect=false}){Timeout=Timeout.InfiniteTimeSpan};using var response=await client.GetAsync(uri,c.Token);if((int)response.StatusCode is >=300 and <400)throw new InvalidOperationException("Redirects are disabled for agent web requests.");response.EnsureSuccessStatusCode();if(response.Content.Headers.ContentLength>2*1024*1024)throw new InvalidOperationException("Web page exceeds the 2 MB limit.");await using var stream=await response.Content.ReadAsStreamAsync(c.Token);using var buffer=new MemoryStream();var chunk=new byte[8192];int read;while((read=await stream.ReadAsync(chunk,c.Token))>0){if(buffer.Length+read>2*1024*1024)throw new InvalidOperationException("Web page exceeds the 2 MB limit.");await buffer.WriteAsync(chunk.AsMemory(0,read),c.Token);}var html=Encoding.UTF8.GetString(buffer.ToArray());html=System.Text.RegularExpressions.Regex.Replace(html,"<(script|style)[^>]*>[\\s\\S]*?</\\1>"," ",System.Text.RegularExpressions.RegexOptions.IgnoreCase|System.Text.RegularExpressions.RegexOptions.CultureInvariant,TimeSpan.FromSeconds(2));var txt=System.Net.WebUtility.HtmlDecode(System.Text.RegularExpressions.Regex.Replace(html,"<[^>]+>"," ",System.Text.RegularExpressions.RegexOptions.CultureInvariant,TimeSpan.FromSeconds(2)));return txt.Length>30000?txt[..30000]+"\n[truncated]":txt;}
   default:throw new InvalidOperationException("Unknown tool.");
  }
 }
 static async Task<string> ReadCappedAsync(StreamReader reader,int limit,CancellationToken token){var output=new StringBuilder();var chars=new char[2048];bool clipped=false;int count;while((count=await reader.ReadAsync(chars.AsMemory(),token))>0){var kept=Math.Min(count,Math.Max(0,limit-output.Length));if(kept>0)output.Append(chars,0,kept);if(kept<count)clipped=true;}return output+(clipped?"\n[truncated]":"");}
 static string SafeWorkspacePath(string path,string workspace){if(!AgentPolicy.Inside(path,workspace))throw new InvalidOperationException("Path is outside the approved workspace.");var root=Path.GetFullPath(workspace);var full=Path.GetFullPath(path,root);var current=root;foreach(var part in Path.GetRelativePath(root,full).Split([Path.DirectorySeparatorChar,Path.AltDirectorySeparatorChar],StringSplitOptions.RemoveEmptyEntries)){current=Path.Combine(current,part);FileSystemInfo info=Directory.Exists(current)?new DirectoryInfo(current):new FileInfo(current);if(info.Exists&&info.LinkTarget is not null){current=info.ResolveLinkTarget(true)?.FullName??throw new InvalidOperationException("Could not resolve a workspace link.");if(!AgentPolicy.Inside(current,root))throw new InvalidOperationException("Workspace links cannot access files outside the workspace.");}}if(!AgentPolicy.Inside(current,root))throw new InvalidOperationException("Path is outside the approved workspace.");return Path.GetFullPath(current);}
 static string Quote(string value)=>"\""+value.Replace("`","``").Replace("\"","`\"")+"\"";
 sealed class McpClient:IDisposable {
  readonly Process process;int id;public List<string> LastImages{get;private set;}=[];
  public McpClient(){var exe=Environment.ProcessPath??"dotnet";var dll=typeof(ChatGptAgentRunner).Assembly.Location;process=new Process{StartInfo=new ProcessStartInfo(exe){UseShellExecute=false,RedirectStandardInput=true,RedirectStandardOutput=true,RedirectStandardError=true,CreateNoWindow=true}};if(Path.GetFileNameWithoutExtension(exe).Equals("dotnet",StringComparison.OrdinalIgnoreCase))process.StartInfo.ArgumentList.Add(dll);process.StartInfo.ArgumentList.Add("--mcp-desktop");foreach(var secret in new[]{"ANTHROPIC_API_KEY","ANTHROPIC_AUTH_TOKEN","OPENAI_API_KEY"})process.StartInfo.Environment.Remove(secret);process.Start();_=process.StandardError.ReadToEndAsync();CallRpc("initialize",new{protocolVersion="2025-06-18",capabilities=new{},clientInfo=new{name="HoiClicky",version="1.0"}});Notify("notifications/initialized",new{});}
  void Notify(string method,object args){process.StandardInput.WriteLine(JsonSerializer.Serialize(new{jsonrpc="2.0",method,@params=args}));process.StandardInput.Flush();}
  JsonElement CallRpc(string method,object args){var n=++id;process.StandardInput.WriteLine(JsonSerializer.Serialize(new{jsonrpc="2.0",id=n,method,@params=args}));process.StandardInput.Flush();while(true){var line=process.StandardOutput.ReadLine()??throw new InvalidOperationException("Desktop tool process stopped.");using var d=JsonDocument.Parse(line);if(d.RootElement.TryGetProperty("id",out var rid)&&rid.GetInt32()==n){if(d.RootElement.TryGetProperty("error",out var er))throw new InvalidOperationException(er.ToString());return d.RootElement.GetProperty("result").Clone();}}}
  public List<JsonElement> ListTools(){var result=CallRpc("tools/list",new{});return result.GetProperty("tools").EnumerateArray().Select(t=>JsonSerializer.Deserialize<JsonElement>(JsonSerializer.Serialize(new{type="function",name="desktop_"+t.GetProperty("name").GetString(),description=t.TryGetProperty("description",out var d)?d.GetString():"Desktop action",parameters=t.GetProperty("inputSchema")}))).ToList();}
  public string Call(string name,JsonElement args,CancellationToken token){token.ThrowIfCancellationRequested();LastImages=[];var r=CallRpc("tools/call",new{name,arguments=args});var text=new List<string>();if(r.TryGetProperty("content",out var content))foreach(var c in content.EnumerateArray()){if(c.TryGetProperty("text",out var t))text.Add(t.GetString()??"");if(c.TryGetProperty("type",out var ty)&&ty.GetString()=="image"&&c.TryGetProperty("data",out var data))LastImages.Add(data.GetString()??"");}return string.Join("\n",text);}
  public void Kill(){try{if(!process.HasExited)process.Kill(true);}catch{}}
  public void Dispose(){Kill();process.Dispose();}
 }
